<script lang="ts">
  // Animated Blackshield knight (Black Steel). Art is generated by
  // openshield/scripts/knight-sprite.py and exported as animated SVGs.
  // Reduced motion: the SVG stops on its first frame, and the <picture>
  // swaps in a still PNG for engines that ignore media queries in SVG images.
  type KnightState = "idle" | "thinking" | "working" | "success" | "error";

  export let state: KnightState = "idle";
  export let size = 64; // rendered width in px; height follows the 32:28 art
  export let label: string | undefined = undefined;
</script>

<picture class="knight" style:width="{size}px" style:height="{(size * 28) / 32}px">
  <source media="(prefers-reduced-motion: reduce)" srcset="/knight/knight-{state}-still.png" />
  <img
    src="/knight/knight-{state}.svg"
    alt={label ?? ""}
    aria-hidden={label ? undefined : "true"}
    width={size}
    height={(size * 28) / 32}
    draggable="false"
  />
</picture>

<style>
  .knight {
    display: inline-block;
    flex: none;
    line-height: 0;
  }
  img {
    width: 100%;
    height: 100%;
    image-rendering: pixelated;
    image-rendering: crisp-edges;
  }
</style>
